from ortools.linear_solver import pywraplp
import json

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define team members and tasks
    members = ['Alex', 'Drew', 'Emery', 'Bailey']
    tasks = ['line inspection', 'inventory sync', 'order batching', 'routing audit']

    # Cost matrix
    costs = [
        [26, 15, 12, 9],    # Alex
        [24, 11, 27, 21],   # Drew
        [23, 12, 23, 15],   # Emery
        [11, 28, 22, 23]    # Bailey
    ]

    # Create decision variables
    x = {}
    for i in range(len(members)):
        for j in range(len(tasks)):
            x[i, j] = solver.IntVar(0, 1, f'x_{i}_{j}')

    # Objective function: minimize total cost
    objective = solver.Objective()
    for i in range(len(members)):
        for j in range(len(tasks)):
            objective.SetCoefficient(x[i, j], costs[i][j])
    objective.SetMinimization()

    # Constraints: each task assigned to exactly one member
    for j in range(len(tasks)):
        constraint = solver.Constraint(1, 1)
        for i in range(len(members)):
            constraint.SetCoefficient(x[i, j], 1)

    # Constraints: each member assigned exactly one task
    for i in range(len(members)):
        constraint = solver.Constraint(1, 1)
        for j in range(len(tasks)):
            constraint.SetCoefficient(x[i, j], 1)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == solver.OPTIMAL:
        print("Optimal assignment found:")
        total_cost = 0
        for i in range(len(members)):
            for j in range(len(tasks)):
                if x[i, j].solution_value() > 0.5:
                    print(f"{members[i]} -> {tasks[j]} (Cost: {costs[i][j]})")
                    total_cost += costs[i][j]
        print(f"Total cost: {total_cost}")
    else:
        print("No optimal solution found")

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

